'use strict';

const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');

const VERSION = '0.76.0';
const ROOT = path.resolve(__dirname, '..');
const SRC_DIR = path.join(ROOT, 'plugin', 'src');
const ENTRY = path.join(SRC_DIR, 'main.lua');
const OUTPUT = path.join(ROOT, 'plugin', 'CodexStudioBridge.plugin.lua');
const INFO = path.join(SRC_DIR, 'generated', 'bundle-info.json');
const MIN_BUNDLE_BYTES = 500000;
const BOM_ERROR = 'BOM/U+FEFF detected; Roblox Lua will fail to parse this plugin.';

function toPosix(value) {
  return value.replace(/\\/g, '/');
}

function relativeFromRoot(filePath) {
  return toPosix(path.relative(ROOT, filePath));
}

function sha256(textOrBuffer) {
  return crypto.createHash('sha256').update(textOrBuffer).digest('hex');
}

function locateIndex(text, index) {
  const before = text.slice(0, index);
  const lines = before.split('\n');
  return {
    line: lines.length,
    column: lines[lines.length - 1].length + 1,
  };
}

function assertNoFeff(text, filePath) {
  const index = text.indexOf('\ufeff');
  if (index === -1) {
    return;
  }
  const location = locateIndex(text, index);
  throw new Error(`${BOM_ERROR} ${relativeFromRoot(filePath)}:${location.line}:${location.column}`);
}

function readFile(filePath) {
  let text = fs.readFileSync(filePath, 'utf8').replace(/\r\n/g, '\n');
  if (text.charCodeAt(0) === 0xfeff) {
    text = text.slice(1);
  }
  assertNoFeff(text, filePath);
  return text;
}

function fileInfo(filePath, content) {
  const body = content == null ? readFile(filePath) : content;
  return {
    path: relativeFromRoot(filePath),
    bytes: Buffer.byteLength(body, 'utf8'),
    sha256: sha256(body),
  };
}

function resolveInclude(includePath, parentFile) {
  if (path.isAbsolute(includePath)) {
    throw new Error(`Absolute include paths are not allowed: ${includePath}`);
  }
  const resolved = path.resolve(path.dirname(parentFile), includePath);
  const relativeToSrc = path.relative(SRC_DIR, resolved);
  if (relativeToSrc.startsWith('..') || path.isAbsolute(relativeToSrc)) {
    throw new Error(`Include escapes plugin/src: ${includePath}`);
  }
  if (!fs.existsSync(resolved)) {
    throw new Error(`Missing include ${includePath} referenced by ${relativeFromRoot(parentFile)}`);
  }
  return resolved;
}

function expandFile(filePath, state) {
  const resolved = path.resolve(filePath);
  if (state.stack.includes(resolved)) {
    const chain = state.stack.concat([resolved]).map(relativeFromRoot).join(' -> ');
    throw new Error(`Circular include detected: ${chain}`);
  }
  const content = readFile(resolved);
  if (!state.seen.has(resolved)) {
    state.seen.add(resolved);
    state.includedFiles.push(fileInfo(resolved, content));
  }
  state.stack.push(resolved);
  const lines = content.split('\n');
  const output = [];
  for (const line of lines) {
    const match = line.match(/^\s*--#include\s+["']([^"']+)["']\s*$/);
    if (match) {
      const child = resolveInclude(match[1], resolved);
      output.push(expandFile(child, state).replace(/\s*$/, ''));
    } else {
      output.push(line);
    }
  }
  state.stack.pop();
  return output.join('\n');
}

function generatedHeader() {
  return [
    '-- Codex Studio Bridge generated bundle',
    `-- Version: ${VERSION}`,
    '-- Source: plugin/src/main.lua',
    '-- Generated by scripts/bundle-plugin.js',
    '-- Do not manually edit bundled output unless emergency patching.',
    '',
  ].join('\n');
}

function buildBundle() {
  if (!fs.existsSync(ENTRY)) {
    throw new Error(`Missing plugin source entry: ${relativeFromRoot(ENTRY)}`);
  }
  const state = { stack: [], seen: new Set(), includedFiles: [] };
  const body = expandFile(ENTRY, state).replace(/\s*$/, '\n');
  const bundle = generatedHeader() + body;
  assertNoFeff(bundle, OUTPUT);
  if (Buffer.byteLength(bundle, 'utf8') < MIN_BUNDLE_BYTES) {
    throw new Error(`Generated bundle is suspiciously small: ${Buffer.byteLength(bundle, 'utf8')} bytes`);
  }
  if (bundle.includes('--#include')) {
    throw new Error('Generated bundle still contains --#include marker');
  }
  return {
    version: VERSION,
    entry: relativeFromRoot(ENTRY),
    output: relativeFromRoot(OUTPUT),
    content: bundle,
    bytes: Buffer.byteLength(bundle, 'utf8'),
    sha256: sha256(bundle),
    includedFiles: state.includedFiles,
  };
}

function writeBundle() {
  const bundle = buildBundle();
  fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
  fs.mkdirSync(path.dirname(INFO), { recursive: true });
  fs.writeFileSync(OUTPUT, bundle.content, 'utf8');
  const info = {
    version: bundle.version,
    generatedAt: new Date().toISOString(),
    entry: bundle.entry,
    output: bundle.output,
    sha256: bundle.sha256,
    bytes: bundle.bytes,
    includedFiles: bundle.includedFiles,
  };
  fs.writeFileSync(INFO, `${JSON.stringify(info, null, 2)}\n`, 'utf8');
  return info;
}

function main() {
  const info = writeBundle();
  console.log(JSON.stringify({ ok: true, ...info }, null, 2));
}

if (require.main === module) {
  try {
    main();
  } catch (err) {
    console.error(err && err.stack ? err.stack : String(err));
    process.exit(1);
  }
}

module.exports = {
  VERSION,
  ROOT,
  SRC_DIR,
  ENTRY,
  OUTPUT,
  INFO,
  buildBundle,
  writeBundle,
  sha256,
  relativeFromRoot,
};
